def transform(grid):
    h, w = len(grid), len(grid[0])

    # The frame color is the most frequent nonzero color.
    counts = {}
    for row in grid:
        for value in row:
            if value:
                counts[value] = counts.get(value, 0) + 1
    frame = max(counts, key=counts.get)

    # The frame's rightmost column marks the end of the panels.
    split = max(c for c in range(w) if any(grid[r][c] == frame for r in range(h)))
    out = [row[:split + 1] for row in grid]

    # Find the colored shapes to the right of the panels.
    objects = {}
    for r in range(h):
        for c in range(split + 1, w):
            value = grid[r][c]
            if value and value != frame:
                objects.setdefault(value, set()).add((r, c))

    def normalize(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    shapes = {}
    for color, cells in objects.items():
        shapes[normalize(cells)] = color

    # Full-frame rows separate the panels.
    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(split + 1))
    ]

    for top, bottom in zip(separators, separators[1:]):
        holes = {
            (r, c)
            for r in range(top + 1, bottom)
            for c in range(split + 1)
            if grid[r][c] == 0
        }
        if not holes:
            continue
        color = shapes.get(normalize(holes))
        if color is not None:
            for r, c in holes:
                out[r][c] = color

    return out
